H.background();
const w = H.W, h = H.H;
const f = Math.max(0.01, P.freq);            // frequency in 10^14 Hz
const c = 3.0e8;                              // speed of light, m/s
const fHz = f * 1e14;
const lam = c / fHz;                          // wavelength in metres
const lamNm = lam * 1e9;                      // wavelength in nm
H.text("Electromagnetic spectrum:  c = lambda * f", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + f.toFixed(2) + " x10^14 Hz    lambda = " + lamNm.toFixed(0) + " nm    c = 3.0x10^8 m/s", 24, 52, { color: H.colors.sub, size: 13 });
// Visible-light colour from wavelength (approx), else grey for non-visible.
function vis(nm){
  let r=0,g=0,b=0;
  if (nm>=380&&nm<440){r=-(nm-440)/60;b=1;}
  else if(nm<490){g=(nm-440)/50;b=1;}
  else if(nm<510){g=1;b=-(nm-510)/20;}
  else if(nm<580){r=(nm-510)/70;g=1;}
  else if(nm<645){r=1;g=-(nm-645)/65;}
  else if(nm<=780){r=1;}
  else {r=g=b=0.35;}
  if(nm<380){r=g=b=0.35;}
  return "rgb("+Math.round(255*H.clamp(r,0,1))+","+Math.round(255*H.clamp(g,0,1))+","+Math.round(255*H.clamp(b,0,1))+")";
}
const col = (lamNm>=380&&lamNm<=780) ? vis(lamNm) : H.colors.accent;
// Draw a travelling wave whose on-screen wavelength tracks the real lambda.
const midY = h*0.55, axL = 60, axR = w-60, span = axR-axL;
H.line(axL, midY, axR, midY, { color: H.colors.axis, width: 1 });
// Map real wavelength (log scale, 1pm .. 1km) to an on-screen pixel wavelength.
const pxLam = H.clamp(H.map(Math.log10(lam), Math.log10(1e-7), Math.log10(5e-7), 30, 180), 18, 240);
const amp = h*0.18, k = H.TAU/pxLam, phase = t*3.0;
const pts = [];
for(let x=axL;x<=axR;x+=2){ pts.push([x, midY - amp*Math.sin(k*(x-axL) - phase)]); }
H.path(pts, { color: col, width: 3 });
// Band label by wavelength.
let band = "gamma";
if (lam>1e-11) band="X-ray";
if (lam>1e-8) band="ultraviolet";
if (lam>=3.8e-7) band="VISIBLE";
if (lam>7.8e-7) band="infrared";
if (lam>1e-3) band="microwave";
if (lam>0.1) band="radio";
H.text(band, w*0.5, midY+amp+34, { color: col, size: 16, weight: 700, align: "center" });
H.text("higher f  ->  shorter lambda  ->  more energy (E = h*f)", 24, h-24, { color: H.colors.sub, size: 12 });
// A photon dot riding the wave to show propagation.
const xd = axL + ((t*120)% span);
H.circle(xd, midY - amp*Math.sin(k*(xd-axL) - phase), 6, { fill: H.colors.warn });
